export function pickLocale(ar: string, en: string | null | undefined, locale: Locale): string {
  if (locale === 'en' && en) return en;
  return ar;
}

function loadLocale(): Locale {
  try {
    const v = localStorage.getItem(STORAGE_KEY);
    if (v === 'en' || v === 'ar') return v;
  } catch {
    /* تجاهل */
  }
  return 'ar';
}

let current: Locale = loadLocale();

const listeners = new Set<(locale: Locale) => void>();

function applyDocument(locale: Locale) {
  if (typeof document === 'undefined') return;
  document.documentElement.lang = locale;
  document.documentElement.dir = locale === 'en' ? 'ltr' : 'rtl';
}

applyDocument(current);

export function getLocale(): Locale {
  return current;
}

export function setLocale(locale: string): Locale {
  current = locale === 'en' ? 'en' : 'ar';
  try {
    localStorage.setItem(STORAGE_KEY, current);
  } catch {
    /* تجاهل */
  }
  applyDocument(current);
  for (const fn of listeners) {
    try {
      fn(current);
    } catch {
      /* تجاهل */
    }
  }
  return current;
}

export function subscribeLocale(fn: (locale: Locale) => void): () => void {
  listeners.add(fn);
  return () => {
    listeners.delete(fn);
  };
}

export function t(key: string, params?: Record<string, string | number>, locale?: Locale): string {
  const loc = locale || current;
  const dict = CATALOGS[loc] || CATALOGS.ar;
  let str = dict[key] !== undefined ? dict[key] : key;
  if (params) {
    for (const [k, v] of Object.entries(params)) {
      str = str.split(`{${k}}`).join(String(v));
    }
  }
  return str;
}